import{_ as l,c as e,o as i,ah as r}from"./chunks/framework.Dnh4IO1K.js";const b=JSON.parse('{"title":"水澤節","description":"周易折中 - 水澤節","frontmatter":{"title":"水澤節","description":"周易折中 - 水澤節"},"headers":[],"relativePath":"classics/zhezhong/066.md","filePath":"classics/zhezhong/066.md"}'),h={name:"classics/zhezhong/066.md"};function p(n,a,d,t,s,o){return i(),e("div",null,[...a[0]||(a[0]=[r('<h1 id="水澤節" tabindex="-1">水澤節 <a class="header-anchor" href="#水澤節" aria-label="Permalink to “水澤節”">​</a></h1><h3 id="程傳" tabindex="-1">程傳 <a class="header-anchor" href="#程傳" aria-label="Permalink to “程傳”">​</a></h3><p>〈節序卦〉：“渙者，離也。物不可以終離，故受之以《節》。物既離散，則當節止之。《節》所以次《渙》也。為卦，澤上有水，澤之容有限，澤上置水，滿則不容，為有節之象，故為《節》。”</p><p>節：亨，苦節不可貞</p><h3 id="本義" tabindex="-1">本義 <a class="header-anchor" href="#本義" aria-label="Permalink to “本義”">​</a></h3><p>節，有限而止也。為卦下兌上坎，澤上有水，其容有限，故為節。節固自有亨道矣，又其體陰陽各半而二五皆陽，故其佔得亨。然至於太甚，則苦矣，故又戒以不可守以為貞也。</p><h3 id="程傳-1" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-1" aria-label="Permalink to “程傳”">​</a></h3><p>事既有節，則能致亨通，故節有亨義。節貴適中，過則苦矣。節至於苦，豈能常也？不可固守以為常，不可貞也。</p><h3 id="集說" tabindex="-1">集說 <a class="header-anchor" href="#集說" aria-label="Permalink to “集說”">​</a></h3><ul><li>孔氏穎逹曰：節者，制度之名，節止之義。制事有節，其道乃亨，故曰“節亨”。節須得中為節，過苦傷於刻薄，物所不堪，不可復正，故曰“苦節不可貞也”。</li></ul><p>孔氏穎逹曰：節者，制度之名，節止之義。制事有節，其道乃亨，故曰“節亨”。節須得中為節，過苦傷於刻薄，物所不堪，不可復正，故曰“苦節不可貞也”。</p><ul><li>薛氏溫其曰：節以禮，其道乃亨。過苦傷陋，不可以為正也。</li></ul><p>薛氏溫其曰：節以禮，其道乃亨。過苦傷陋，不可以為正也。</p><p>象曰：澤上有水，節；君子以制數度，議德行</p><h3 id="程傳-2" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-2" aria-label="Permalink to “程傳”">​</a></h3><p>澤之容水有限，過則盈溢，是有節，故為節也。君子觀節之象，以制立數度。凡物之大小、輕重、高下、文質，皆有數度，所以為節也。數多寡，度法制。議德行者，存諸中為德，發於外為行。人之德行當議，則中節。議謂商度求中節也。</p><h3 id="集說-1" tabindex="-1">集說 <a class="header-anchor" href="#集說-1" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>侯氏行果曰 ：澤上有水，以堤防為節。</p></li><li><p>張氏浚曰 ：數度之制因乎人，德行之議自於已。記曰：“君子議道自己而置法以民。”蓋已之所不能行，與其所不可行而強於人，誰其從之？一言盡節之道，中而已。中必自身始也。</p></li><li><p>朱氏震曰 ：澤之容水固有限量，虛則納之，滿則洩之。水以澤為節也。</p></li><li><p>郭氏雍曰 ：澤無水則為不足，澤上有水則為有餘。不足則為困，有餘則當節。理之常也。在人之節，則制數度所以節於外，議德行所以節於內也。為國為家，至於一身，其內外製節皆一也。</p></li><li><p>孔氏穎逹曰 ：數度謂尊卑禮命之多少，德行謂人才堪任之優劣。君子象節以制其禮數等差，皆使有度；議人之德行，任用皆使得宜。</p></li></ul><h3 id="案" tabindex="-1">案 <a class="header-anchor" href="#案" aria-label="Permalink to “案”">​</a></h3><p>議德行，諸儒皆謂一身之德行。獨孔氏謂在人之德行，於“議”字尤切，且得“愛爵祿”、“愼名器”之意。</p><p>彖曰：節 亨，剛柔分而剛得中</p><h3 id="本義-1" tabindex="-1">本義 <a class="header-anchor" href="#本義-1" aria-label="Permalink to “本義”">​</a></h3><p>以卦體釋卦辭。</p><h3 id="程傳-3" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-3" aria-label="Permalink to “程傳”">​</a></h3><p>節之道，自有亨義。事有節則能亨也。又卦之才，剛柔分處，剛得中而不過，亦所以為節，所以能亨也。</p><h3 id="集說-2" tabindex="-1">集說 <a class="header-anchor" href="#集說-2" aria-label="Permalink to “集說”">​</a></h3><ul><li>趙氏玉泉曰：統觀全體而剛柔適均，則剛以濟柔，柔以濟剛，一張一弛，惟其稱也。折觀二體而二五得中，則不失之過，不失之不及，一損一益，惟其宜也。由是以制數度而隆殺皆中，以議徳行而進反皆中，此節之所以亨也。</li></ul><p>苦節不可貞，其道窮也</p><h3 id="本義-2" tabindex="-1">本義 <a class="header-anchor" href="#本義-2" aria-label="Permalink to “本義”">​</a></h3><p>又以理言。</p><h3 id="程傳-4" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-4" aria-label="Permalink to “程傳”">​</a></h3><p>節至於極而苦，則不可堅固常守其道也，窮極也。</p><h3 id="集說-3" tabindex="-1">集說 <a class="header-anchor" href="#集說-3" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>孔氏穎逹曰：若以苦節為正，則其道困窮。</p></li><li><p>吳氏應回曰：中節則和，否則不和。稼穡作甘，以得中央之土也；火炎上則苦，亦以焦枯之極也。剛得中而能節，乃為九五之甘；柔失中而過節，則為上六之苦。故物得中則甘，失中則苦。</p></li><li><p>俞氏琰曰：凡物過節，則苦味之過、正形之過、勞心之過思，皆謂之苦節，而苦則非通行之道，故曰其道窮也。</p></li><li><p>黃氏淳耀曰：合於中即甘即亨，失其中即苦即窮。苦與甘反，窮與亨反。</p></li></ul><p>說以行險，當位以節，中正以通</p><h3 id="本義-3" tabindex="-1">本義 <a class="header-anchor" href="#本義-3" aria-label="Permalink to “本義”">​</a></h3><p>又以卦體卦徳言之，當位中正指五，又坎為通。</p><h3 id="程傳-5" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-5" aria-label="Permalink to “程傳”">​</a></h3><p>以卦才言也。內兌外坎，說以行險也。人於所說，則不知已遇艱險，則思止。方說而止，為節之義。當位以節，五居尊當位也，在澤上有節也。當位而以節主節者也，處得中正，節而能通也。中正則通，過則苦矣。</p><h3 id="集說-4" tabindex="-1">集說 <a class="header-anchor" href="#集說-4" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>孔氏穎逹曰：更就二體及四五當位，重釋行節得亨之義，以明苦節之窮也。</p></li><li><p>林氏希元曰：九五陽剛居尊，當位以主節於上，而所節者得其中正，是可以通行於天下。</p></li></ul><h3 id="案-1" tabindex="-1">案 <a class="header-anchor" href="#案-1" aria-label="Permalink to “案”">​</a></h3><p>說以行險，先儒說義未明。葢節有阻塞難行之象，所謂險也，而其所以亨者，則以其有安適之善而無拘迫之苦，所謂說也。當位以位言，中正以徳言。當位則有節天下之權，中正則能通天下之志。此三句當依孔氏為總申彖辭之義，說則不苦而通則不窮矣。葢上文既以全卦之善言之，此又專主九五及卦徳以申之，正與漸卦同例。</p><p>天地節而四時成，節以制度，不傷財不害民</p><h3 id="本義-4" tabindex="-1">本義 <a class="header-anchor" href="#本義-4" aria-label="Permalink to “本義”">​</a></h3><p>極言節道。</p><h3 id="程傳-6" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-6" aria-label="Permalink to “程傳”">​</a></h3><p>推言節之道，天地有節故能成四時，無節則失序也。聖人立制度以為節，故能不傷財害民。人慾之無窮也，苟非節以制度，則侈肆至於傷財害民矣。</p><h3 id="集說-5" tabindex="-1">集說 <a class="header-anchor" href="#集說-5" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>孔氏穎逹曰：天地以氣序為節，使寒暑往來各以其序，則四時功成也。王者以制度為節，使用之有道，役之有時，則不傷財不害民也。</p></li><li><p>吳氏曰：慎曰“革”，曰“天地革而四時成”，此曰“天地節而四時成”。限止之謂節，改易之謂革。節淺而革深，節先而革後。四時舉其大者言之，天地之化刻刻相節，時時相革。</p></li></ul><p>初九：不出戶庭，無咎。</p><h3 id="本義-5" tabindex="-1">本義 <a class="header-anchor" href="#本義-5" aria-label="Permalink to “本義”">​</a></h3><p>戶庭，戶外之庭也。陽剛得正，居節之初，未可以行，能節而止者也。故其象佔如此。</p><h3 id="程傳-7" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-7" aria-label="Permalink to “程傳”">​</a></h3><p>戶庭，戶外之庭；門庭，門內之庭。初以陽在下，上覆有應，非能節者也。又當節之初，故戒之。謹守至於不出戶庭，則無咎也。初能固守，終或渝之；不謹於初，安能有卒？故於節之初為戒甚嚴也。</p><h3 id="集說-6" tabindex="-1">集說 <a class="header-anchor" href="#集說-6" aria-label="Permalink to “集說”">​</a></h3><ul><li>王氏申子曰：陽剛在下，居得其正，當節之初，知其時未可行，故謹言謹行，至於不出戶外之庭，是知節而能止者，故無咎。</li></ul><p>王氏申子曰：陽剛在下，居得其正，當節之初，知其時未可行，故謹言謹行，至於不出戶外之庭，是知節而能止者，故無咎。</p><ul><li>徐氏在漢曰：坎變下一畫為兌，象止。坎下流，戶以節人之出入，澤以節水之出入。初不出戶庭，以極其愼宻為不出，此其所以無咎。</li></ul><p>徐氏在漢曰：坎變下一畫為兌，象止。坎下流，戶以節人之出入，澤以節水之出入。初不出戶庭，以極其愼宻為不出，此其所以無咎。</p><p>象曰：不出戶庭，知通塞也</p><h3 id="程傳-8" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-8" aria-label="Permalink to “程傳”">​</a></h3><p>爻辭於節之初，戒之謹守，故云“不出戶庭，則無咎也”。象恐人之泥於言也，故復明之雲：雖當謹守，不出戶庭，又必知時之通塞也。通則行，塞則止。義當出則出矣。尾生之信，水至不去，不知通塞也。故君子貞而不諒，繫辭所解獨以言者，在人所節，唯言與行。節於言，則行可知。言當在先也。</p><h3 id="集說-7" tabindex="-1">集說 <a class="header-anchor" href="#集說-7" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>王氏申子曰 ：時有通塞，通則行，塞則止。當止即止，其知通塞之君子乎？繫辭專以愼密言語說之，兌體故也。</p></li><li><p>吳氏曰 ：愼曰節，兼通塞。言猶艮之兼行止言也。初九“不出戶庭”，知塞也，而兼言知通者，見其非一於止者也。二失時極則，但知塞而不知通矣。</p></li></ul><p>九二：不出門庭，兇。</p><h3 id="本義-6" tabindex="-1">本義 <a class="header-anchor" href="#本義-6" aria-label="Permalink to “本義”">​</a></h3><p>門庭，門內之庭也。九二當可行之時而失剛不正，上無應與，知節而不知通，故其象佔如此。</p><h3 id="程傳-9" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-9" aria-label="Permalink to “程傳”">​</a></h3><p>二雖剛中之質，然處陰居說而承柔，處陰不正也，居說失剛也，承柔近邪也。節之道當以剛中正，二失其剛中之德，與九五剛中正異矣。不出門庭，不之於外也，謂不從於五也。二五非陰陽正應，故不相從。若以剛中之道相合，則可以成節之功。惟其失徳失時，是以兇也。不合於五，乃不正之節也。以剛中正為節，如懲忿窒欲，損過益有餘是也；不正之節，如嗇節於用，懦節於行是也。</p><h3 id="集說-8" tabindex="-1">集說 <a class="header-anchor" href="#集說-8" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>朱子語類雲：戶庭是初爻之象，門庭是第二爻之象。</p></li><li><p>錢氏志立曰：澤所以鍾水也，水始至則増其防以瀦之，初九是也；水漸盛則啟其竇以洩之，九二是也。二與初同道，則失其節矣。</p></li></ul><h3 id="案-2" tabindex="-1">案 <a class="header-anchor" href="#案-2" aria-label="Permalink to “案”">​</a></h3><p>節卦六爻皆以澤水二體取義。澤者止水，者行。節雖以止為義，然必可以通行而不窮，乃為節之亨也。初二兩爻，一在澤底，一在澤中。在澤底者，水之方瀦，不出宜也；在澤中，則當有蓄洩之道，不可閉塞而不出也。兌本坎體中爻，其主也，有坎之德可以流行而變，兌則為下流之塞。二適當之，故六爻之失時未有如二者也。時應塞而塞，則為慎宻不出，雖足不窺戶可也；時不應塞而塞，則為絕物自廢，所謂“出門同人”者安在哉？</p><p>象曰：不出門庭，兇；失時極也</p><h3 id="程傳-10" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-10" aria-label="Permalink to “程傳”">​</a></h3><p>不能上從九五剛中正之道，成節之功乃繫於私暱之陰柔，是失時之至極，所以兇也。失時，失其所宜也。</p><h3 id="集說-9" tabindex="-1">集說 <a class="header-anchor" href="#集說-9" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>蘇氏軾曰 ：水之始至澤，當塞而不當通；既至，當通而不當塞。故初九以“不出戶庭”為無咎，言當塞也；九二以“不出門庭”為兇，言當通也。至是而不通，則失時而至於極。</p></li><li><p>郭氏雍曰 ：初為不當有事之地，而二以剛中居有為之位，其道不可同也。故初以“不出戶庭”為知塞，而二以“不出門庭”為不知通。知塞故無咎，不知通則有失時之兇矣。</p></li></ul><p>六三：不節若，則嗟若，無咎。</p><h3 id="本義-7" tabindex="-1">本義 <a class="header-anchor" href="#本義-7" aria-label="Permalink to “本義”">​</a></h3><p>陰柔而不中正，以當節時，非能節者，故其象佔如此。</p><h3 id="程傳-11" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-11" aria-label="Permalink to “程傳”">​</a></h3><p>六三不中正，乘剛而臨險，固宜有咎。然柔順而和說，若能自節而順於義，則可以無過；不然，則兇咎必至，可傷嗟也。故不節若，則嗟若，己所自致，無所歸咎也。</p><h3 id="集說-10" tabindex="-1">集說 <a class="header-anchor" href="#集說-10" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>張子曰：處非其位，失節也。然能嗟其不節，則亦無咎矣。 又曰：王弼於此“無咎”又別立一例，只舊例亦可推行。但能嗟其不節，有補過之心，則亦無咎也。</p></li><li><p>又曰：王弼於此“無咎”又別立一例，只舊例亦可推行。但能嗟其不節，有補過之心，則亦無咎也。</p></li><li><p>李氏彥章曰：臨之六三失臨之道而既憂之，節之六三失節之道而嗟若，皆得無咎。易以補過為善者也。</p></li><li><p>鄭氏汝諧曰：進乘二陽，處澤之溢，過乎中而不節者三也。知其不節而能傷嗟以自悔，其誰咎之哉？下體之極，極則當變，故發此義。</p></li><li><p>豐氏寅初曰：處兌之極，水溢澤上，說於驕侈，不知謹節以致窮困。然其心痛悔形於悲嘆，能悔則有改過之㡬，是猶可以無咎也。</p></li></ul><p>象曰：不節之嗟，又誰咎也</p><h3 id="本義-8" tabindex="-1">本義 <a class="header-anchor" href="#本義-8" aria-label="Permalink to “本義”">​</a></h3><p>此“無咎”與諸爻異，言無所歸咎也。</p><h3 id="程傳-12" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-12" aria-label="Permalink to “程傳”">​</a></h3><p>節則可以免過，而不能自節以致可嗟，將誰咎乎？</p><h3 id="集說-11" tabindex="-1">集說 <a class="header-anchor" href="#集說-11" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>沈氏一貫曰 ：王介甫、程沙隨謂能嗟怨自治，亦無咎。嗟與戚、嗟若之嗟同，“又誰咎”與“出門”、“同人”之象同。</p></li><li><p>何氏楷曰 ：諸卦爻辭言“無咎”者九十有九，多補過之辭。解三爻傳“又誰咎”語雖與此同，然爻辭未嘗有“無咎”字。</p></li></ul><p>六四：安節亨。</p><h3 id="本義-9" tabindex="-1">本義 <a class="header-anchor" href="#本義-9" aria-label="Permalink to “本義”">​</a></h3><p>柔順得正，上承九五，自然有節者也。故其象佔如此。</p><h3 id="程傳-13" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-13" aria-label="Permalink to “程傳”">​</a></h3><p>四順承九五剛中正之道，是以中正為節也。以陰居陰，安於正也。當位為有節之象，下應於初。四坎體水也，水上溢為無節，就下有節也。如四之義，非強節之，安於節者也，故能致亨。節以安為善，強守而不安，則不能當，豈能亨也？</p><h3 id="集說-12" tabindex="-1">集說 <a class="header-anchor" href="#集說-12" aria-label="Permalink to “集說”">​</a></h3><ul><li>俞氏琰曰：六三失位而處兌澤之極，是乃溢而不節；六四當位而順承九五之君，故為安節。案六四以柔正承五，故曰“安節”。安與勉對，葢凡其制節謹度，皆循乎成法而安行，非勉強以為節者也。於象居坎之下，水之下流也，柔正為水流平地、安瀾之象。</li></ul><p>象曰：安節之亨，承上道也</p><h3 id="程傳-14" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-14" aria-label="Permalink to “程傳”">​</a></h3><p>四能安節之義非一，象獨舉其重者。上承九五剛中正之道以為節，足以亨矣。餘善亦不出於中正也。</p><h3 id="集說-13" tabindex="-1">集說 <a class="header-anchor" href="#集說-13" aria-label="Permalink to “集說”">​</a></h3><ul><li>錢氏一本曰 ：中正之通在五，四以近承不以徒止為功，更以通行為道，故曰“承上道也”。</li></ul><h3 id="案-3" tabindex="-1">案 <a class="header-anchor" href="#案-3" aria-label="Permalink to “案”">​</a></h3><p>節曰“亨”為九五中正以通也。而亨於四言之者，五者水之源也，四者水之流也。水之通在流，承上之源而布之者也。</p><p>九五：甘節，吉；往有尚。</p><h3 id="本義-10" tabindex="-1">本義 <a class="header-anchor" href="#本義-10" aria-label="Permalink to “本義”">​</a></h3><p>所謂當位以節，中正以通者也。故其象佔如此。</p><h3 id="程傳-15" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-15" aria-label="Permalink to “程傳”">​</a></h3><p>九五剛中正，居尊位，為節之主，所謂當位以節，中正以通者也。在己則安行，天下則說從，節之甘美者也，其吉可知。以此而行，其功大矣，故往則有可嘉尚也。</p><h3 id="集說-14" tabindex="-1">集說 <a class="header-anchor" href="#集說-14" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>王氏弼曰：當位居中，為節之主，不失其中，不傷財不害民之謂也。為節而不苦，非甘而何？術斯以往，往有尚也。</p></li><li><p>朱子語類雲：甘便對那苦。甘節與“禮之用和為貴”相似。</p></li><li><p>趙氏汝梅曰：鹹苦酸辛，味之偏；甘，味之中也。甘受和，和者節味之偏而適其中。行之以甘，人不吾病而事以成，節之吉也。</p></li></ul><h3 id="案-4" tabindex="-1">案 <a class="header-anchor" href="#案-4" aria-label="Permalink to “案”">​</a></h3><p>水之止者苦，積澤為滷是也；其流者甘，山下出泉是也。五為坎主，水之源也。在井為冽，取其不泥；在節為甘，取其不苦也。</p><p>象曰：甘節之吉，居位中也</p><h3 id="程傳-16" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-16" aria-label="Permalink to “程傳”">​</a></h3><p>既居尊位，又得中道，所以吉而有功。節以中為貴，得中則正矣，正不能盡中也。</p><h3 id="集說-15" tabindex="-1">集說 <a class="header-anchor" href="#集說-15" aria-label="Permalink to “集說”">​</a></h3><ul><li>俞氏琰曰 ：節貴乎中。當節而不節，則六三有“不節之嗟”；過於節，則上六有“苦節之兇”。惟九五“甘節”而吉者，蓋居位之中，當位以節，無過無不及也。</li></ul><p>上六：苦節貞兇，悔亡。</p><h3 id="本義-11" tabindex="-1">本義 <a class="header-anchor" href="#本義-11" aria-label="Permalink to “本義”">​</a></h3><p>居節之極，故為苦節。既處過極，故雖得正而不免於兇。然禮奢寧儉，故雖有悔而終得亡之也。</p><h3 id="程傳-17" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-17" aria-label="Permalink to “程傳”">​</a></h3><p>上六居節之極，節之苦者也。居險之極，亦為苦義。固守則兇，悔則兇亡，悔損過從中之謂也。節之悔亡與他卦之悔亡辭同而義異也。</p><h3 id="集說-16" tabindex="-1">集說 <a class="header-anchor" href="#集說-16" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>幹氏寶曰：彖稱“苦節不可貞”，在此爻也，故曰“貞兇”。</p></li><li><p>孔氏穎逹曰：上六處節之極，過節之中節，不能甘以至於苦，故曰“苦節”也。若以苦節施人，則是正道之兇；若以苦節脩身，則儉約無妄，可得亡悔。</p></li><li><p>呂氏大臨曰：上六居節之極，其節己甚，苦節者也。用過乎節，物所不堪守，是不變物窮必乖，故曰“貞兇”。禮奢寧儉，未害乎義，故曰“悔亡”。</p></li><li><p>胡氏炳文曰：五位中，故為甘；上位極，故為苦。彖曰“節亨”，五以之；曰“苦節不可貞”，上以之。</p></li><li><p>來氏知德曰：無甘節之吉，故貞兇；無不節之嗟，故悔亡。</p></li></ul><p>象曰：苦節貞兇，其道窮也</p><h3 id="程傳-18" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-18" aria-label="Permalink to “程傳”">​</a></h3><p>節既苦而貞，固守之則兇，蓋節之道至於窮極矣。</p><h3 id="集說-17" tabindex="-1">集說 <a class="header-anchor" href="#集說-17" aria-label="Permalink to “集說”">​</a></h3><ul><li>吳氏曰 ：愼曰爻言“苦節貞兇”，彖言“苦節不可貞”。惟其貞兇，是以不可貞也。故彖、象傳皆以其道窮也釋之。</li></ul><p>總論</p><ul><li><p>丘氏富國曰：彖傳“當位以節”，故節之六爻以當位為善，不當位為不善。若以兩爻相比者觀之，則又各相比而相反。初與二比，初不出戶庭則無咎，二不出門庭則兇，二反乎初者也；三與四比，四柔得正則為安節，三柔不正則為不節，三反乎四者也；五與上比，五得中則為節之甘，上過中則為節之苦，上反乎五者也。</p></li><li><p>陸氏振奇曰：觀下卦“通塞”二字，上卦“甘苦”二字，可以知節道矣。通處味甘，塞處味苦；塞極必潰，故三受焉；甘失反苦，故上受焉。</p></li></ul><h3 id="案-5" tabindex="-1">案 <a class="header-anchor" href="#案-5" aria-label="Permalink to “案”">​</a></h3><p>下卦為澤為止，故初二皆曰“不出”；三則澤之止而溢也。上卦為水為流，故四曰“安”而五曰“甘”，上則水之流而竭也。通塞甘苦，皆從澤水取義，陸氏之說得之矣。</p>',137)])])}const m=l(h,[["render",p]]);export{b as __pageData,m as default};
